Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;
const int MOD=1e9+7;
const int MAX=1<<20;
int n,limit,result,p1_array[MAX],p2_array[MAX];
int flag_grid[10][10],a_grid[10][10],h_array[10][10][10];

int fast_pow(int base, int exp) {
    int res=1;
    while (exp) {
        if (exp & 1) res=1LL*res*base%MOD;
        base=1LL*base*base%MOD;
        exp>>=1;
    }
    return res;
}

int modular_inverse(int x) { return fast_pow(x,MOD-2); }

bool check_triplet(int x,int y,int z) {
    int arr[3]={x,y,z},d[3]={0,1,2};
    do {
        if (flag_grid[arr[d[0]]][1] && flag_grid[arr[d[1]]][2] && flag_grid[arr[d[2]]][3]) return true;
    } while (next_permutation(d,d+3));
    return false;
}

void explore_first(int P,int x,int y) {
    if (x==7 && y==1) {
        int state=0;
        for (int i=1; i<=6; i++)
            for (int j=i+1; j<=6; j++)
                for (int k=j+1; k<=6; k++) 
                    if (check_triplet(i,j,k)) {
                        int X=1;
                        while (X==i || X==j || X==k) X++;
                        int Y=X+1;
                        while (Y==i || Y==j || Y==k) Y++;
                        int Z=Y+1;
                        while (Z==i || Z==j || Z==k) Z++;
                        state|=h_array[X][Y][Z];
                    }
        p1_array[state]=(p1_array[state]+P)%MOD;
        return;
    }
    flag_grid[x][y]=1;
    if (y==3) explore_first(1LL*P*a_grid[x][y]%MOD,x+1,1);
    else explore_first(1LL*P*a_grid[x][y]%MOD,x,y+1);
    flag_grid[x][y]=0;
    if (y==3) explore_first(1LL*P*(MOD+1-a_grid[x][y])%MOD,x+1,1);
    else explore_first(1LL*P*(MOD+1-a_grid[x][y])%MOD,x,y+1);
}

void explore_second(int P,int x,int y) {
    if (x==7 && y==4) {
        int state=0;
        for (int i=1; i<=6; i++)
            for (int j=i+1; j<=6; j++)
                for (int k=j+1; k<=6; k++) 
                    if (check_triplet(i,j,k)) state|=h_array[i][j][k];
        p2_array[state]=(p2_array[state]+P)%MOD;
        result=(result+1LL*p1_array[limit^state]*P%MOD)%MOD;
        return;
    }
    flag_grid[x][y-3]=1;
    if (y==6) explore_second(1LL*P*a_grid[x][y]%MOD,x+1,4);
    else explore_second(1LL*P*a_grid[x][y]%MOD,x,y+1);
    flag_grid[x][y-3]=0;
    if (y==6) explore_second(1LL*P*(MOD+1-a_grid[x][y])%MOD,x+1,4);
    else explore_second(1LL*P*(MOD+1-a_grid[x][y])%MOD,x,y+1);
}

int main() {
    scanf("%d",&n);
    for (int i=1; i<=n; i++)
        for (int j=1; j<=n; j++)
            scanf("%d",&a_grid[i][j]),a_grid[i][j]=1LL*a_grid[i][j]*modular_inverse(100)%MOD;
    for (int i=n+1; i<=6; i++) a_grid[i][i]=1;
    int total=0;
    for (int i=1; i<=6; i++)
        for (int j=i+1; j<=6; j++)
            for (int k=j+1; k<=6; k++) 
                h_array[i][j][k]=1<<total++;
    explore_first(1,1,1);
    limit=(1<<20)-1;
    for (int i=0; i<=19; i++)
        for (int j=0; j<=limit; j++) 
            if (j>>i&1) p1_array[j]=(p1_array[j]+p1_array[j^1<<i])%MOD;
    explore_second(1,1,4);
    result=(MOD+1-result)%MOD;
    printf("%d\n",result);
    return 0;
}
